using EscolaEvolucional.Api.DTOs.Turma;
using System; using System.Collections.Generic; using System.Linq;
namespace EscolaEvolucional.Api.Infrastructure.Cache { public sealed class MemoryTurmaCache : ITurmaCache { private sealed class Entrada { public IReadOnlyList<TurmaResponseDto> Turmas; public DateTime ExpiraEmUtc; } private readonly object _sync=new object(); private readonly TimeSpan _duracao; private readonly Dictionary<string,Entrada> _entradas=new Dictionary<string,Entrada>(); public MemoryTurmaCache(TimeSpan duracao){if(duracao<=TimeSpan.Zero)throw new ArgumentOutOfRangeException(nameof(duracao));_duracao=duracao;} public bool TentarObter(string chave,out IReadOnlyList<TurmaResponseDto> turmas){Validar(chave);lock(_sync){Entrada e;if(!_entradas.TryGetValue(chave,out e)||DateTime.UtcNow>=e.ExpiraEmUtc){_entradas.Remove(chave);turmas=null;return false;}turmas=Copiar(e.Turmas);return true;}} public void Armazenar(string chave,IEnumerable<TurmaResponseDto> turmas){Validar(chave);if(turmas==null)throw new ArgumentNullException(nameof(turmas));lock(_sync){_entradas[chave]=new Entrada{Turmas=Copiar(turmas),ExpiraEmUtc=DateTime.UtcNow.Add(_duracao)};}} public void Invalidar(string chave){Validar(chave);lock(_sync){_entradas.Remove(chave);}} private static void Validar(string chave){if(string.IsNullOrWhiteSpace(chave))throw new ArgumentException("A chave de cache é obrigatória.",nameof(chave));} private static IReadOnlyList<TurmaResponseDto> Copiar(IEnumerable<TurmaResponseDto> turmas){return turmas.Select(t=>new TurmaResponseDto{Id=t.Id,Nome=t.Nome,Periodo=t.Periodo,VagasTotal=t.VagasTotal,VagasDisponiveis=t.VagasDisponiveis}).ToList();} } }